export CLAUDE_PROJECT_DIR="/private/tmp/claude-501/pr86-ci-live/lt/runs/sysspec115/fx" && cd -- "$CLAUDE_PROJECT_DIR" && [ "$(pwd -P)" = "$CLAUDE_PROJECT_DIR" ] && python3 -c '
import json
d=json.load(open("candidate-import.json"))
print(list(d.keys()))
for a in d.get("artifacts",[]):
  print("---",{k:(v if not isinstance(v,(dict,list)) or k in ("classification","source_lineage","implementation_readiness") else type(v).__name__+str(len(v))) for k,v in a.items()})
