    if k in a: print(k, list(a[k].keys()) if isinstance(a[k],dict) else [x.get("operation") for x in a[k]])
for k,v in d.items():
  if k!="artifacts": print(k, json.dumps(v,ensure_ascii=False)[:400])
'

